public static str getPolicyHelpText(str _policyName)
{
    TreeNode        policyNode;
    TreeNode        constraintsNode;
    str             aotPath;
    str             helpText;
    str             primaryTable;
    str             policyLabel;
    str             constrainedTablesStr;
    List            tableList = new List(Types::String);
    ListIterator    iterator;
    int             tableCount = 0;

    aotPath    = strFmt(@"\Security\Policies\%1", _policyName);
    policyNode = TreeNode::findNode(aotPath);

    if (!policyNode)
    {
        return strFmt("Policy '%1' not found.", _policyName);
    }

    // Get policy label
    policyLabel = policyNode.AOTgetProperty('Label');

    // If label is a label ID (e.g., @MET:PolicyLabel), resolve it
    if (policyLabel && subStr(policyLabel, 1, 1) == '@')
    {
        policyLabel = SysLabel::labelId2String(policyLabel);
    }

    // Fallback to policy name if no label
    if (!policyLabel)
    {
        policyLabel = _policyName;
    }

    // Get primary table
    primaryTable = policyNode.AOTgetProperty('PrimaryTable');

    // Add primary table if constrained
    if (policyNode.AOTgetProperty('ConstrainedTable') == 'Yes' && primaryTable)
    {
        tableList.addEnd(primaryTable);
    }

    // Get all constrained tables
    constraintsNode = policyNode.AOTfindChild('Constrained Tables');

    if (constraintsNode)
    {
        METSecurityPolicyHelper::collectTableNames(constraintsNode, tableList);
    }

    // Build comma-separated table list
    tableCount = tableList.elements();
    iterator = new ListIterator(tableList);

    while (iterator.more())
    {
        if (constrainedTablesStr)
        {
            constrainedTablesStr += ', ';
        }
        constrainedTablesStr += iterator.value();
        iterator.next();
    }

    // Build help text with dynamic label
    helpText =  strFmt("Site restrictions will be applied to users assigned the '%1' role.\n", policyLabel);
    helpText += strFmt("The policy restricts data access across the following %1 table(s).\n",
                     tableCount);
    helpText += strFmt("Primary table: %1.\n", primaryTable);
    helpText += strFmt("Constrained tables: %1.", constrainedTablesStr);

    return helpText;
}

/// <summary>
/// Collects table names recursively into a list
/// </summary>
private static void collectTableNames(TreeNode _parentNode, List _tableList)
{
    TreeNode    currentNode;
    str         tableName;

    currentNode = _parentNode.AOTfirstChild();

    while (currentNode)
    {
        tableName = currentNode.AOTgetProperty('Name');

        if (!tableName)
        {
            tableName = currentNode.AOTname();
        }

        if (tableName && !METSecurityPolicyHelper::listContains(_tableList, tableName))
        {
            _tableList.addEnd(tableName);
        }

        // Recursively process children
        if (currentNode.AOTfirstChild())
        {
            METSecurityPolicyHelper::collectTableNames(currentNode, _tableList);
        }

        currentNode = currentNode.AOTnextSibling();
    }
}

/// <summary>
/// Checks if list contains a value
/// </summary>
private static boolean listContains(List _list, str _value)
{
    ListIterator iterator = new ListIterator(_list);

    while (iterator.more())
    {
        if (iterator.value() == _value)
        {
            return true;
        }
        iterator.next();
    }

    return false;
}

public static void getAllConstrainedTables(str _policyName)
{
    TreeNode    policyNode;
    TreeNode    constraintsNode;
    str         aotPath;
    Set         tableSet = new Set(Types::String);

    aotPath    = strFmt(@"\Security\Policies\%1", _policyName);
    policyNode = TreeNode::findNode(aotPath);

    if (policyNode)
    {
        // Get primary table if constrained
        if (policyNode.AOTgetProperty('ConstrainedTable') == 'Yes')
        {
            tableSet.add(policyNode.AOTgetProperty('PrimaryTable'));
        }

        // Get root constrained tables node
        constraintsNode = policyNode.AOTfindChild('Constrained Tables');

        if (constraintsNode)
        {
            METSecurityPolicyHelper::traverseTableNodes(constraintsNode, tableSet);
        }

        // Output results
        SetEnumerator enumerator = tableSet.getEnumerator();
        while (enumerator.moveNext())
        {
            info(strFmt("Constrained Table: %1", enumerator.current()));
        }
    }
}

private static void traverseTableNodes(TreeNode _parentNode, Set _tableSet)
{
    TreeNode    currentNode;
    str         tableName;

    currentNode = _parentNode.AOTfirstChild();

    while (currentNode)
    {
        // Get table name
        tableName = currentNode.AOTgetProperty('Name');

        if (!tableName)
        {
            tableName = currentNode.AOTname();
        }

        if (tableName)
        {
            _tableSet.add(tableName);
        }

        // Recursively process children directly under this table node
        if (currentNode.AOTfirstChild())
        {
            METSecurityPolicyHelper::traverseTableNodes(currentNode, _tableSet);
        }

        currentNode = currentNode.AOTnextSibling();
    }
}
